INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Apa singkatan dari HTML?', '{"A": "HyperText Markup Language", "B": "HighText Machine Language", "C": "HyperText and links Markup Language", "D": "HomeTool Markup Language"}', 'A', 'HTML adalah singkatan dari HyperText Markup Language, bahasa markup standar untuk membuat halaman web.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Tag HTML mana yang digunakan untuk membuat heading utama?', '{"A": "<head>", "B": "<h1>", "C": "<header>", "D": "<heading>"}', 'B', 'Tag <h1> digunakan untuk heading utama, diikuti oleh <h2>, <h3>, dll untuk sub-heading.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Tag HTML mana yang digunakan untuk membuat paragraf?', '{"A": "<p>", "B": "<para>", "C": "<paragraph>", "D": "<text>"}', 'A', 'Tag <p> digunakan untuk membuat paragraf teks.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Atribut HTML mana yang digunakan untuk memberikan ID unik pada elemen?', '{"A": "class", "B": "id", "C": "name", "D": "unique"}', 'B', 'Atribut id digunakan untuk memberikan identifikasi unik pada elemen HTML.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Tag HTML mana yang digunakan untuk membuat link?', '{"A": "<link>", "B": "<a>", "C": "<href>", "D": "<url>"}', 'B', 'Tag <a> (anchor) digunakan untuk membuat hyperlink ke halaman lain atau bagian dalam halaman.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Tag HTML mana yang digunakan untuk menampilkan gambar?', '{"A": "<image>", "B": "<img>", "C": "<picture>", "D": "<photo>"}', 'B', 'Tag <img> digunakan untuk menampilkan gambar dengan atribut src untuk menentukan lokasi gambar.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Apa fungsi dari tag <br>?', '{"A": "Membuat baris baru", "B": "Membuat paragraf baru", "C": "Membuat heading", "D": "Membuat list"}', 'A', 'Tag <br> digunakan untuk membuat line break atau baris baru.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Tag HTML mana yang digunakan untuk membuat list tidak berurutan?', '{"A": "<list>", "B": "<ul>", "C": "<ol>", "D": "<li>"}', 'B', 'Tag <ul> (unordered list) digunakan untuk membuat list dengan bullet points.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Atribut HTML mana yang digunakan untuk memberikan style CSS inline?', '{"A": "style", "B": "css", "C": "class", "D": "inline"}', 'A', 'Atribut style digunakan untuk menambahkan CSS inline langsung pada elemen HTML.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'HTML Basics Quiz' LIMIT 1), 'Tag HTML mana yang digunakan untuk membuat tabel?', '{"A": "<table>", "B": "<tab>", "C": "<grid>", "D": "<data>"}', 'A', 'Tag <table> digunakan sebagai container untuk membuat tabel HTML.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Apa tipe data yang digunakan untuk menyimpan teks di JavaScript?', '{"A": "string", "B": "text", "C": "char", "D": "word"}', 'A', 'String adalah tipe data yang digunakan untuk menyimpan teks atau karakter di JavaScript.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Operator apa yang digunakan untuk membandingkan nilai dan tipe data?', '{"A": "==", "B": "===", "C": "=", "D": "!="}', 'B', 'Operator === (strict equality) membandingkan baik nilai maupun tipe data.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Fungsi JavaScript mana yang digunakan untuk menampilkan pesan di console?', '{"A": "alert()", "B": "print()", "C": "console.log()", "D": "display()"}', 'C', 'console.log() digunakan untuk menampilkan pesan di console browser untuk debugging.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Cara mana yang benar untuk mendeklarasikan variabel di JavaScript modern?', '{"A": "var myVar;", "B": "let myVar;", "C": "const myVar;", "D": "Semua benar"}', 'D', 'JavaScript modern menggunakan let dan const untuk mendeklarasi variabel, meskipun var masih didukung.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Apa hasil dari 5 + "5" di JavaScript?', '{"A": "10", "B": "55", "C": "Error", "D": "undefined"}', 'B', 'JavaScript melakukan type coercion, mengubah angka 5 menjadi string sehingga hasilnya adalah "55".');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Metode array mana yang digunakan untuk menambahkan elemen di akhir array?', '{"A": "push()", "B": "add()", "C": "append()", "D": "insert()"}', 'A', 'Metode push() menambahkan satu atau lebih elemen di akhir array dan mengembalikan panjang array baru.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Struktur kontrol mana yang digunakan untuk mengeksekusi kode berulang?', '{"A": "if-else", "B": "switch", "C": "for", "D": "try-catch"}', 'C', 'Loop for digunakan untuk mengeksekusi blok kode berulang kali selama kondisi tertentu terpenuhi.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Apa itu DOM dalam konteks JavaScript?', '{"A": "Document Object Model", "B": "Data Object Management", "C": "Dynamic Object Method", "D": "Display Object Model"}', 'A', 'DOM (Document Object Model) adalah representasi struktur HTML sebagai objek yang dapat dimanipulasi dengan JavaScript.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Fungsi JavaScript mana yang digunakan untuk menunda eksekusi kode?', '{"A": "delay()", "B": "wait()", "C": "setTimeout()", "D": "pause()"}', 'C', 'setTimeout() menjadwalkan eksekusi fungsi setelah waktu tertentu dalam milidetik.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Apa itu callback function di JavaScript?', '{"A": "Fungsi yang dipanggil kembali", "B": "Fungsi yang dipanggil sebagai argumen", "C": "Fungsi yang mengembalikan nilai", "D": "Fungsi yang tidak memiliki parameter"}', 'B', 'Callback function adalah fungsi yang diberikan sebagai argumen ke fungsi lain dan dipanggil ketika operasi selesai.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Metode string mana yang digunakan untuk mengubah string menjadi huruf besar?', '{"A": "toUpper()", "B": "upperCase()", "C": "toUpperCase()", "D": "makeUpper()"}', 'C', 'Metode toUpperCase() mengubah semua karakter dalam string menjadi huruf besar.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Operator apa yang digunakan untuk spread syntax di JavaScript?', '{"A": "...", "B": "***", "C": "&&&", "D": "|||"}', 'A', 'Operator spread (...) digunakan untuk menyebarkan elemen array atau properti objek.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Apa itu Promise di JavaScript?', '{"A": "Janji untuk mengeksekusi kode", "B": "Objek yang mewakili penyelesaian operasi async", "C": "Fungsi yang mengembalikan nilai", "D": "Variabel global"}', 'B', 'Promise adalah objek yang mewakili penyelesaian (atau kegagalan) operasi asynchronous dan nilai yang dihasilkan.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Sintaks mana yang benar untuk arrow function?', '{"A": "function() => {}", "B": "() => {}", "C": "=> () {}", "D": "function => () {}"}', 'B', 'Sintaks arrow function adalah () => {} untuk fungsi tanpa parameter.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'JavaScript Quiz' LIMIT 1), 'Apa itu hoisting di JavaScript?', '{"A": "Mengangkat variabel ke atas", "B": "Menurunkan variabel ke bawah", "C": "Menghapus variabel", "D": "Mengganti nama variabel"}', 'A', 'Hoisting adalah perilaku JavaScript di mana deklarasi variabel dan fungsi diangkat ke atas scope mereka sebelum eksekusi kode.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu React?', '{"A": "Database", "B": "JavaScript library untuk UI", "C": "CSS framework", "D": "Server"}', 'B', 'React adalah library JavaScript untuk membangun user interface yang interaktif dan efisien.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu JSX?', '{"A": "JavaScript XML", "B": "Java Syntax Extension", "C": "JSON XML", "D": "JavaScript Extension"}', 'A', 'JSX adalah ekstensi sintaks untuk JavaScript yang memungkinkan penulisan HTML dalam kode React.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Hook mana yang digunakan untuk state management di React?', '{"A": "useState", "B": "useEffect", "C": "useContext", "D": "useReducer"}', 'A', 'useState adalah hook fundamental untuk menambahkan state ke komponen fungsional.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu props di React?', '{"A": "Properti komponen", "B": "Parameter yang diteruskan ke komponen", "C": "State internal komponen", "D": "Event handler"}', 'B', 'Props adalah parameter yang diteruskan dari komponen induk ke komponen anak.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Hook mana yang digunakan untuk efek samping di React?', '{"A": "useState", "B": "useEffect", "C": "useMemo", "D": "useCallback"}', 'B', 'useEffect digunakan untuk menangani efek samping seperti fetching data, subscriptions, atau DOM manipulation.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu Virtual DOM?', '{"A": "Copy dari real DOM", "B": "Representasi ringan dari UI di memori", "C": "Database virtual", "D": "DOM yang tidak terlihat"}', 'B', 'Virtual DOM adalah representasi ringan dari UI yang disimpan di memori dan disinkronkan dengan real DOM.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Metode lifecycle mana yang dipanggil ketika komponen akan dihapus?', '{"A": "componentDidMount", "B": "componentDidUpdate", "C": "componentWillUnmount", "D": "render"}', 'C', 'componentWillUnmount dipanggil tepat sebelum komponen dihapus dari DOM.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu key prop di React?', '{"A": "Password untuk komponen", "B": "Identifier unik untuk list items", "C": "CSS class", "D": "Event handler"}', 'B', 'Key prop membantu React mengidentifikasi item mana yang telah berubah, ditambahkan, atau dihapus dalam list.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Hook mana yang digunakan untuk mengoptimalkan performa dengan memoization?', '{"A": "useState", "B": "useEffect", "C": "useMemo", "D": "useRef"}', 'C', 'useMemo mengembalikan nilai memoized dari komputasi yang mahal dan hanya menghitung ulang ketika dependencies berubah.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu controlled component?', '{"A": "Komponen yang dikontrol oleh parent", "B": "Form element yang nilainya dikontrol oleh React state", "C": "Komponen yang tidak bisa diubah", "D": "Komponen dengan banyak props"}', 'B', 'Controlled component adalah form element di mana nilai dikontrol oleh state React.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa fungsi dari useCallback hook?', '{"A": "Membuat state", "B": "Memoize fungsi", "C": "Menangani event", "D": "Mengambil data"}', 'B', 'useCallback mengembalikan versi memoized dari callback yang hanya berubah jika dependencies berubah.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'React Quiz' LIMIT 1), 'Apa itu React Fragment?', '{"A": "Potongan kode React", "B": "Wrapper yang tidak menambah elemen DOM", "C": "Error handling", "D": "State management"}', 'B', 'React Fragment memungkinkan mengelompokkan multiple elemen tanpa menambah node ekstra ke DOM.');
