INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Apa yang dimaksud dengan desain grafis?', '{"A": "Seni memasak", "B": "Seni visual untuk menyampaikan pesan", "C": "Teknik programming", "D": "Analisis data"}', 'B', 'Desain grafis adalah seni dan praktik visual untuk menyampaikan ide dan pesan melalui gambar, teks, dan bentuk.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Elemen dasar desain yang paling fundamental adalah?', '{"A": "Warna", "B": "Garis", "C": "Tekstur", "D": "Ruang"}', 'B', 'Garis adalah elemen paling dasar dalam desain, bisa lurus, lengkung, tebal, atau tipis.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Prinsip desain yang menarik perhatian dengan perbedaan adalah?', '{"A": "Balance", "B": "Contrast", "C": "Emphasis", "D": "Movement"}', 'B', 'Contrast adalah prinsip desain yang menggunakan perbedaan untuk menarik perhatian dan membuat elemen menonjol.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Warna primer dalam teori warna adalah?', '{"A": "Hijau, Orange, Ungu", "B": "Merah, Kuning, Biru", "C": "Hitam, Putih, Abu", "D": "Pink, Biru muda, Kuning"}', 'B', 'Warna primer adalah Merah, Kuning, dan Biru yang tidak bisa dibuat dari campuran warna lain.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Font family yang cocok untuk heading adalah?', '{"A": "Sans-serif", "B": "Serif", "C": "Script", "D": "Display"}', 'D', 'Display fonts biasanya digunakan untuk heading karena memiliki karakter yang menarik dan mudah dibaca dalam ukuran besar.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Rule of Thirds membagi area desain menjadi?', '{"A": "4 bagian", "B": "6 bagian", "C": "9 bagian", "D": "12 bagian"}', 'C', 'Rule of Thirds membagi area menjadi 9 bagian dengan 2 garis horizontal dan 2 garis vertikal.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Software yang digunakan untuk editing foto profesional adalah?', '{"A": "Adobe Illustrator", "B": "Adobe Photoshop", "C": "Adobe InDesign", "D": "CorelDRAW"}', 'B', 'Adobe Photoshop adalah software utama untuk editing foto dan gambar raster.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Jenis desain yang digunakan untuk identitas merek adalah?', '{"A": "Poster Design", "B": "Logo Design", "C": "Banner Design", "D": "Packaging Design"}', 'B', 'Logo design adalah desain yang digunakan untuk menciptakan identitas visual merek perusahaan.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Tahap pertama dalam proses desain adalah?', '{"A": "Sketch", "B": "Brief", "C": "Digital Draft", "D": "Final"}', 'B', 'Brief adalah tahap pertama dimana desainer memahami kebutuhan dan requirement dari klien.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Tren desain 2024 yang menekankan kesederhanaan adalah?', '{"A": "3D Design", "B": "Minimalism", "C": "Gradient", "D": "Typography"}', 'B', 'Minimalism adalah tren desain yang menekankan kesederhanaan namun tetap powerful dan efektif.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Platform untuk mencari inspirasi desain adalah?', '{"A": "GitHub", "B": "Behance", "C": "Stack Overflow", "D": "Docker Hub"}', 'B', 'Behance adalah platform populer untuk mencari inspirasi dan showcase karya desain grafis.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Soft skill yang penting untuk desainer grafis adalah?', '{"A": "Programming", "B": "Creativity", "C": "Data Analysis", "D": "Accounting"}', 'B', 'Creativity adalah soft skill utama yang dibutuhkan desainer grafis untuk menghasilkan ide-ide inovatif.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Komponen utama dalam membangun portfolio desainer adalah?', '{"A": "Personal Website", "B": "Social Media Posts", "C": "Email Collection", "D": "Business Cards"}', 'A', 'Personal website adalah komponen utama portfolio untuk showcase karya desain secara profesional.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Design Principles Quiz' LIMIT 1), 'Apa yang dimaksud dengan white space dalam desain?', '{"A": "Area berwarna putih", "B": "Ruang kosong yang strategis", "C": "Background transparan", "D": "Border putih"}', 'B', 'White space adalah ruang kosong yang sengaja dibiarkan kosong untuk meningkatkan readability dan estetika.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Apa yang dimaksud dengan jaringan komputer?', '{"A": "Sistem komputer tunggal", "B": "Kumpulan komputer yang terhubung", "C": "Software antivirus", "D": "Program office"}', 'B', 'Jaringan komputer adalah sistem yang menghubungkan komputer dan perangkat lain untuk berbagi sumber daya dan berkomunikasi.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Tipe jaringan berdasarkan jangkauan yang paling luas adalah?', '{"A": "PAN", "B": "LAN", "C": "MAN", "D": "WAN"}', 'D', 'WAN (Wide Area Network) memiliki jangkauan nasional atau global, seperti internet.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Topologi jaringan dimana semua perangkat terhubung ke satu kabel utama adalah?', '{"A": "Star", "B": "Ring", "C": "Bus", "D": "Mesh"}', 'C', 'Topologi bus menghubungkan semua perangkat ke satu kabel utama (backbone).');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Layer dalam model OSI yang bertanggung jawab untuk routing adalah?', '{"A": "Physical", "B": "Data Link", "C": "Network", "D": "Transport"}', 'C', 'Layer Network (layer 3) bertanggung jawab untuk routing dan logical addressing seperti IP address.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Protokol transport layer yang reliable dan connection-oriented adalah?', '{"A": "UDP", "B": "TCP", "C": "IP", "D": "ICMP"}', 'B', 'TCP (Transmission Control Protocol) adalah protokol connection-oriented yang menjamin delivery data.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Perangkat jaringan yang menghubungkan perangkat dalam LAN adalah?', '{"A": "Router", "B": "Modem", "C": "Switch", "D": "Firewall"}', 'C', 'Switch menghubungkan perangkat dalam Local Area Network dan mengatur traffic berdasarkan MAC address.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Standar WiFi terbaru dengan kecepatan tinggi adalah?', '{"A": "802.11n", "B": "802.11ac", "C": "802.11ax", "D": "802.11g"}', 'C', '802.11ax (WiFi 6) adalah standar terbaru dengan kecepatan tinggi dan efisiensi energi yang lebih baik.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Teknik keamanan jaringan yang mengenkripsi data dalam transit adalah?', '{"A": "Firewall", "B": "VPN", "C": "Antivirus", "D": "Proxy"}', 'B', 'VPN (Virtual Private Network) mengenkripsi data dan membuat tunnel aman untuk transmisi data.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Command untuk mengecek konektivitas jaringan adalah?', '{"A": "ipconfig", "B": "ping", "C": "netstat", "D": "tracert"}', 'B', 'Ping digunakan untuk menguji konektivitas dan latency ke host tertentu.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Teknologi cloud networking yang memungkinkan isolasi jaringan virtual adalah?', '{"A": "CDN", "B": "VPC", "C": "Load Balancer", "D": "DNS"}', 'B', 'VPC (Virtual Private Cloud) memungkinkan pembuatan jaringan virtual terisolasi di cloud environment.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Protokol yang digunakan untuk mengirim email adalah?', '{"A": "HTTP", "B": "FTP", "C": "SMTP", "D": "DNS"}', 'C', 'SMTP (Simple Mail Transfer Protocol) adalah protokol standar untuk mengirim email melalui internet.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Teknologi yang memungkinkan multiple device terhubung ke internet melalui satu koneksi adalah?', '{"A": "Router", "B": "Switch", "C": "NAT", "D": "DHCP"}', 'C', 'NAT (Network Address Translation) memungkinkan multiple device menggunakan satu public IP address.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Sertifikasi fundamental networking dari CompTIA adalah?', '{"A": "CCNA", "B": "Network+", "C": "MCSE", "D": "RHCE"}', 'B', 'CompTIA Network+ adalah sertifikasi fundamental untuk networking yang diakui industri.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Computer Networking Quiz' LIMIT 1), 'Teknologi yang menggunakan gelombang radio untuk komunikasi jarak jauh adalah?', '{"A": "Fiber Optic", "B": "Twisted Pair", "C": "Microwave", "D": "Coaxial"}', 'C', 'Microwave menggunakan gelombang radio untuk komunikasi point-to-point jarak jauh.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Apa yang dimaksud dengan telekomunikasi?', '{"A": "Komunikasi lokal", "B": "Transmisi informasi jarak jauh", "C": "Komunikasi tatap muka", "D": "Komunikasi tertulis"}', 'B', 'Telekomunikasi adalah teknologi yang memungkinkan transmisi informasi melalui jarak jauh menggunakan berbagai media.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Penemu telephone adalah?', '{"A": "Thomas Edison", "B": "Alexander Graham Bell", "C": "Nikola Tesla", "D": "Guglielmo Marconi"}', 'B', 'Alexander Graham Bell menemukan telephone pada tahun 1876.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Media transmisi dengan bandwidth tertinggi adalah?', '{"A": "Twisted Pair", "B": "Coaxial Cable", "C": "Fiber Optic", "D": "Wireless"}', 'C', 'Fiber optic memiliki bandwidth tertinggi dan kecepatan transmisi yang sangat tinggi.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Generasi jaringan seluler terkini adalah?', '{"A": "3G", "B": "4G LTE", "C": "5G", "D": "6G"}', 'C', '5G adalah generasi jaringan seluler terkini dengan kecepatan ultra-high dan latency rendah.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Teknik modulasi yang digunakan untuk radio AM adalah?', '{"A": "FM", "B": "PM", "C": "AM", "D": "FSK"}', 'C', 'AM (Amplitude Modulation) digunakan dalam radio AM dimana informasi dikodekan dalam amplitudo gelombang pembawa.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Satelit yang mengorbit pada ketinggian 36.000 km adalah?', '{"A": "LEO", "B": "MEO", "C": "GEO", "D": "HEO"}', 'C', 'GEO (Geostationary Earth Orbit) satelit mengorbit pada ketinggian 36.000 km dan terlihat stationary dari bumi.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Protokol yang digunakan untuk VoIP signaling adalah?', '{"A": "HTTP", "B": "SIP", "C": "SMTP", "D": "FTP"}', 'B', 'SIP (Session Initiation Protocol) adalah protokol signaling yang digunakan untuk menginisiasi, memelihara, dan mengakhiri sesi komunikasi real-time.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Teknologi wireless jarak dekat untuk device connectivity adalah?', '{"A": "WiFi", "B": "Bluetooth", "C": "NFC", "D": "GPS"}', 'B', 'Bluetooth adalah teknologi wireless untuk konektivitas jarak dekat antara device seperti headset, keyboard, dan smartphone.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Sistem telekomunikasi yang mengintegrasikan voice, data, dan video adalah?', '{"A": "PSTN", "B": "ISDN", "C": "VoIP", "D": "GSM"}', 'B', 'ISDN (Integrated Services Digital Network) mengintegrasikan berbagai jenis layanan telekomunikasi dalam satu jaringan digital.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Teknik multiplexing yang membagi waktu menjadi slot adalah?', '{"A": "FDM", "B": "TDM", "C": "CDMA", "D": "OFDM"}', 'B', 'TDM (Time Division Multiplexing) membagi waktu menjadi slot temporal untuk multiple sinyal.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Operator telekomunikasi terbesar di Indonesia adalah?', '{"A": "Indosat", "B": "XL", "C": "Telkom", "D": "Tri"}', 'C', 'Telkom adalah operator telekomunikasi terbesar di Indonesia dengan jaringan terluas.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Teknologi yang menggunakan cahaya untuk transmisi data adalah?', '{"A": "Radio", "B": "Microwave", "C": "Fiber Optic", "D": "Satellite"}', 'C', 'Fiber optic menggunakan cahaya untuk transmisi data dengan kecepatan tinggi dan jarak jauh.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Frekuensi yang digunakan untuk komunikasi seluler 5G adalah?', '{"A": "600 MHz", "B": "2.4 GHz", "C": "Sub-6 GHz dan mmWave", "D": "30 GHz"}', 'C', '5G menggunakan frekuensi sub-6 GHz untuk coverage luas dan mmWave (millimeter wave) untuk kecepatan tinggi.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Protokol internet yang menyediakan secure communication adalah?', '{"A": "HTTP", "B": "HTTPS", "C": "FTP", "D": "SMTP"}', 'B', 'HTTPS (HTTP Secure) menggunakan SSL/TLS untuk mengenkripsi komunikasi web.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Telecommunications Quiz' LIMIT 1), 'Teknologi emerging yang menggunakan light untuk wireless communication adalah?', '{"A": "LiFi", "B": "WiFi", "C": "Bluetooth", "D": "NFC"}', 'A', 'LiFi (Light Fidelity) adalah teknologi wireless yang menggunakan cahaya LED untuk transmisi data.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Apa yang dimaksud dengan database?', '{"A": "Program aplikasi", "B": "Kumpulan data terorganisir", "C": "Sistem operasi", "D": "Bahasa pemrograman"}', 'B', 'Database adalah kumpulan data yang terorganisir dan tersimpan secara sistematis untuk akses dan manipulasi yang mudah.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Model database relasional menggunakan konsep?', '{"A": "Hierarki", "B": "Tabel dan relasi", "C": "Objek", "D": "Dokumen"}', 'B', 'Database relasional menggunakan tabel (relations) dengan baris dan kolom, dan relasi antar tabel.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Bahasa query standar untuk database relasional adalah?', '{"A": "HTML", "B": "CSS", "C": "SQL", "D": "JavaScript"}', 'C', 'SQL (Structured Query Language) adalah bahasa standar untuk mengelola dan memanipulasi database relasional.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Kunci utama (primary key) dalam tabel berfungsi untuk?', '{"A": "Mengenkripsi data", "B": "Mengidentifikasi unik setiap record", "C": "Menyimpan data besar", "D": "Membuat backup"}', 'B', 'Primary key secara unik mengidentifikasi setiap record dalam tabel dan tidak boleh duplikat.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Normalisasi database bertujuan untuk?', '{"A": "Mempercepat query", "B": "Mengurangi redundansi data", "C": "Meningkatkan security", "D": "Memperbesar storage"}', 'B', 'Normalisasi bertujuan mengurangi redundansi data dan meningkatkan integritas data dalam database.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Jenis relasi many-to-many dalam ER diagram ditandai dengan?', '{"A": "Garis lurus", "B": "Simbol crow''s foot", "C": "Lingkaran", "D": "Kotak"}', 'B', 'Crow''s foot notation digunakan untuk menunjukkan relasi many-to-many dalam Entity Relationship diagram.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Perintah SQL untuk mengambil data dari tabel adalah?', '{"A": "INSERT", "B": "UPDATE", "C": "SELECT", "D": "DELETE"}', 'C', 'SELECT digunakan untuk mengambil/query data dari satu atau lebih tabel dalam database.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Konsep ACID dalam database management system meliputi?', '{"A": "Atomicity, Consistency, Isolation, Durability", "B": "Access, Control, Integrity, Data", "C": "Application, Connection, Interface, Database", "D": "Array, Class, Instance, Definition"}', 'A', 'ACID adalah properti yang menjamin keandalan transaksi database: Atomicity, Consistency, Isolation, Durability.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Database NoSQL cocok digunakan untuk data yang?', '{"A": "Terstruktur dan relasional", "B": "Besar, tidak terstruktur, real-time", "C": "Kecil dan sederhana", "D": "Statis dan jarang berubah"}', 'B', 'NoSQL database dirancang untuk menangani big data, data tidak terstruktur, dan aplikasi real-time.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Index dalam database berfungsi untuk?', '{"A": "Mengenkripsi data", "B": "Mempercepat pencarian data", "C": "Menyimpan backup", "D": "Mengkompres data"}', 'B', 'Index adalah struktur data yang mempercepat operasi pencarian dan query pada kolom tertentu.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Foreign key dalam tabel relasional mereferensi?', '{"A": "Primary key tabel lain", "B": "Data eksternal", "C": "File sistem", "D": "Memory cache"}', 'A', 'Foreign key adalah kolom yang mereferensi primary key dari tabel lain untuk membuat relasi.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Perintah SQL untuk menambahkan data baru ke tabel adalah?', '{"A": "SELECT", "B": "INSERT", "C": "UPDATE", "D": "CREATE"}', 'B', 'INSERT digunakan untuk menambahkan record/baris data baru ke dalam tabel.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Database management system populer open source adalah?', '{"A": "Oracle", "B": "SQL Server", "C": "MySQL", "D": "DB2"}', 'C', 'MySQL adalah DBMS open source yang paling populer dan banyak digunakan untuk aplikasi web.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Database Design Quiz' LIMIT 1), 'Konsep denormalisasi dalam database design digunakan untuk?', '{"A": "Mengurangi redundansi", "B": "Mempercepat query read", "C": "Menghemat storage", "D": "Meningkatkan security"}', 'B', 'Denormalisasi menambahkan redundansi data untuk mempercepat operasi read pada database yang sering diakses.');
