INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Graphic Design Tools Quiz' LIMIT 1), 'Software yang digunakan untuk vektor graphics adalah?', '{"A": "Adobe Photoshop", "B": "Adobe Illustrator", "C": "Adobe InDesign", "D": "CorelDRAW"}', 'B', 'Adobe Illustrator adalah software utama untuk desain vektor.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Graphic Design Tools Quiz' LIMIT 1), 'Tool di Photoshop untuk memilih area berbentuk persegi panjang adalah?', '{"A": "Lasso Tool", "B": "Magic Wand", "C": "Rectangular Marquee", "D": "Brush Tool"}', 'C', 'Rectangular Marquee Tool digunakan untuk memilih area persegi panjang.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Graphic Design Tools Quiz' LIMIT 1), 'Software yang digunakan untuk layout dan publishing adalah?', '{"A": "Adobe Photoshop", "B": "Adobe Illustrator", "C": "Adobe InDesign", "D": "Adobe Premiere"}', 'C', 'Adobe InDesign adalah software untuk layout dan publishing.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Graphic Design Tools Quiz' LIMIT 1), 'Tool di Illustrator untuk membuat bentuk dasar seperti lingkaran adalah?', '{"A": "Pen Tool", "B": "Shape Builder", "C": "Ellipse Tool", "D": "Type Tool"}', 'C', 'Ellipse Tool digunakan untuk membuat bentuk oval dan lingkaran.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Color Theory Quiz' LIMIT 1), 'Warna yang dihasilkan dari campuran merah dan kuning adalah?', '{"A": "Hijau", "B": "Orange", "C": "Ungu", "D": "Biru"}', 'B', 'Merah + Kuning = Orange dalam teori warna.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Color Theory Quiz' LIMIT 1), 'Kontras warna yang memberikan kesan tenang adalah?', '{"A": "Merah vs Hijau", "B": "Biru vs Orange", "C": "Biru vs Hijau", "D": "Merah vs Kuning"}', 'C', 'Biru dan hijau adalah warna analog yang memberikan kesan harmonis.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Color Theory Quiz' LIMIT 1), 'Warna primer dalam model RGB adalah?', '{"A": "Merah, Kuning, Biru", "B": "Merah, Hijau, Biru", "C": "Cyan, Magenta, Yellow", "D": "Hitam, Putih, Abu"}', 'B', 'RGB menggunakan Merah, Hijau, Biru sebagai warna primer.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Color Theory Quiz' LIMIT 1), 'Prinsip warna yang menunjukkan keseimbangan adalah?', '{"A": "Hue", "B": "Saturation", "C": "Value", "D": "Balance"}', 'D', 'Balance dalam warna menciptakan harmoni visual.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Typography Quiz' LIMIT 1), 'Jenis font yang memiliki kaki pada huruf adalah?', '{"A": "Sans-serif", "B": "Serif", "C": "Script", "D": "Display"}', 'B', 'Serif fonts memiliki kaki atau stroke tambahan pada huruf.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Typography Quiz' LIMIT 1), 'Spacing antara karakter dalam typography disebut?', '{"A": "Kerning", "B": "Leading", "C": "Tracking", "D": "Alignment"}', 'C', 'Tracking adalah spacing keseluruhan antara karakter.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Typography Quiz' LIMIT 1), 'Font family yang mudah dibaca untuk body text adalah?', '{"A": "Arial", "B": "Times New Roman", "C": "Comic Sans", "D": "Impact"}', 'B', 'Times New Roman adalah serif font yang readable untuk body text.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Typography Quiz' LIMIT 1), 'Ukuran font yang standar untuk heading adalah?', '{"A": "8-10 pt", "B": "12-14 pt", "C": "18-24 pt", "D": "36-48 pt"}', 'C', '18-24 pt cocok untuk heading agar menonjol.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Network Security Quiz' LIMIT 1), 'Teknik keamanan yang mengubah data menjadi kode tidak dapat dibaca adalah?', '{"A": "Firewall", "B": "Encryption", "C": "Antivirus", "D": "Backup"}', 'B', 'Encryption mengubah data menjadi format yang tidak dapat dibaca tanpa kunci.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Network Security Quiz' LIMIT 1), 'Perangkat yang memfilter traffic jaringan berdasarkan aturan adalah?', '{"A": "Router", "B": "Switch", "C": "Firewall", "D": "Modem"}', 'C', 'Firewall memfilter traffic masuk dan keluar berdasarkan aturan keamanan.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Network Security Quiz' LIMIT 1), 'Serangan dimana penyerang menyamar sebagai entitas tepercaya adalah?', '{"A": "Virus", "B": "Phishing", "C": "Spoofing", "D": "Malware"}', 'C', 'Spoofing adalah teknik dimana penyerang menyamar sebagai host yang sah.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Network Security Quiz' LIMIT 1), 'Protokol yang menyediakan secure communication melalui internet adalah?', '{"A": "HTTP", "B": "HTTPS", "C": "FTP", "D": "SMTP"}', 'B', 'HTTPS menggunakan SSL/TLS untuk secure communication.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Wireless Networking Quiz' LIMIT 1), 'Standar WiFi yang mendukung kecepatan hingga 54 Mbps adalah?', '{"A": "802.11a", "B": "802.11b", "C": "802.11g", "D": "802.11n"}', 'C', '802.11g mendukung kecepatan hingga 54 Mbps.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Wireless Networking Quiz' LIMIT 1), 'Frekuensi yang digunakan oleh WiFi 2.4 GHz adalah?', '{"A": "2.4 GHz", "B": "5 GHz", "C": "2.4 dan 5 GHz", "D": "6 GHz"}', 'A', 'WiFi 2.4 GHz menggunakan frekuensi 2.4 GHz.');
INSERT INTO public.quiz_questions (quiz_id, question_text, options, correct_answer, explanation) VALUES ((SELECT id FROM public.quizzes WHERE title = 'Wireless Networking Quiz' LIMIT 1), 'Teknologi wireless untuk koneksi jarak dekat adalah?', '{"A": "WiFi", "B": "Bluetooth", "C": "NFC", "D": "GPS"}', 'B', 'Bluetooth digunakan untuk koneksi wireless jarak dekat.');
